#!/usr/bin/env python3
"""Generate all 92 primitive instructions and 23 free equality tests."""
from pathlib import Path

import round35_1980_half_parameter_pell_certificate as certificate
from round24_26_1980_schedule_tables import generate


if __name__ == "__main__":
    generate(certificate, 92, "92")
    output = (Path(__file__).resolve().parent.parent / "1980"
              / "jones1980_theorem5_92_schedule.tex")
    text = output.read_text(encoding="utf-8")
    text = text.replace("Generated by round24_26_1980_schedule_tables.py",
                        "Generated by round35_1980_schedule_table.py")
    assert text.count("The twenty-two free equality tests are") == 1
    text = text.replace("The twenty-two free equality tests are",
                        "The twenty-three free equality tests are")
    assert len(certificate.EQUALITIES) == 23
    output.write_text(text, encoding="utf-8", newline="\n")
